changeSet.sql:
ALTER TABLE nexus.pdf_pipeline
    ADD COLUMN run_epoch INTEGER NOT NULL DEFAULT 0;
COMMENT ON COLUMN nexus.pdf_pipeline.run_epoch IS
    'Ownership generation of this run (nexus-8vu8p, pipeline-003-run-epoch.xml): SET run_epoch = run_epoch + 1 in the same UPDATE as every takeover (create''s resuming branch and its completed-leftover reset), returned by POST /v1/pipeline/create, and compared under SELECT ... FOR UPDATE by every write route that receives run_epoch; a mismatch is 409 stale_run and writes nothing. A request without run_epoch (a client older than this changeset) is unfenced.';
